{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import * as commands from './commands.js'
import { parseInput } from './parser.js'
import { Graph } from './graph.js'

function usageError() {
  process.stderr.write('error: usage: cli.js waves|explain|pack <workers>\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)

  // Parse command-line arguments
  if (args.length === 0) {
    usageError()
  }

  const command = args[0]

  if (command === 'waves') {
    if (args.length !== 1) {
      usageError()
    }
  } else if (command === 'explain') {
    if (args.length !== 1) {
      usageError()
    }
  } else if (command === 'pack') {
    if (args.length !== 2) {
      usageError()
    }
    // Validate worker count
    const workers = args[1]
    if (!/^\d+$/.test(workers) || workers === '0' || workers.startsWith('0')) {
      process.stderr.write('error: workers must be a positive integer\n')
      process.exit(2)
    }
  } else {
    usageError()
  }

  // Read input from stdin
  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch (e) {
    process.stderr.write('error: failed to read stdin\n')
    process.exit(2)
  }

  // Parse input
  let tasks, deps
  try {
    ;[tasks, deps] = parseInput(input)
  } catch (err) {
    process.stderr.write(err.message + '\n')
    process.exit(err.code || 2)
  }

  // Build graph
  const graph = new Graph(tasks, deps)

  // Check for cycles
  const cycle = graph.detectCycle()
  if (cycle) {
    process.stderr.write('error: cycle: ' + cycle.join(' -> ') + '\n')
    process.exit(3)
  }

  // Execute command
  try {
    if (command === 'waves') {
      commands.waves(graph)
    } else if (command === 'explain') {
      commands.explain(graph)
    } else if (command === 'pack') {
      const workerCount = parseInt(args[1], 10)
      commands.pack(graph, workerCount)
    }
  } catch (err) {
    process.stderr.write(err.message + '\n')
    process.exit(2)
  }
}

main()
"}

