{"file_path":"src/parser.js","content":"/**
 * Parse the input graph format.
 */

const VALID_NAME_PATTERN = /^[A-Za-z0-9_.\-]+$/
const VALID_TASK_NAME_PATTERN = /^[A-Za-z0-9_.\-]+$/

export function parseInput(input) {
  const lines = input.split('\n')
  const tasks = new Map() // name -> cost
  const deps = new Map() // name -> Set of dependencies
  const declaredAt = new Map() // name -> line number

  let lineNum = 0
  for (const rawLine of lines) {
    lineNum++

    // Trim the line
    const line = rawLine.trim()

    // Skip empty lines and comments
    if (!line || line.startsWith('#')) {
      continue
    }

    // Split on whitespace
    const words = line.split(/\s+/)

    if (words.length === 0) {
      continue
    }

    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw {
          code: 2,
          message: `error: line ${lineNum}: expected task <name> <cost>`
        }
      }

      const name = words[1]
      const costStr = words[2]

      // Validate name
      if (!VALID_TASK_NAME_PATTERN.test(name)) {
        throw {
          code: 2,
          message: `error: line ${lineNum}: invalid task name ${name}`
        }
      }

      // Validate cost
      if (!/^\d+$/.test(costStr)) {
        throw {
          code: 2,
          message: `error: line ${lineNum}: cost must be a non-negative integer`
        }
      }

      const cost = parseInt(costStr, 10)

      // Check for duplicate
      if (tasks.has(name)) {
        throw {
          code: 2,
          message: `error: line ${lineNum}: task ${name} is declared twice`
        }
      }

      tasks.set(name, cost)
      declaredAt.set(name, lineNum)

      // Initialize deps if not present
      if (!deps.has(name)) {
        deps.set(name, new Set())
      }
    } else if (directive === 'dep') {
      if (words.length < 2) {
        throw {
          code: 2,
          message: `error: line ${lineNum}: expected dep <name> <dependency>...`
        }
      }

      const name = words[0]
      const dependencies = words.slice(1)

      // Initialize deps set if not present
      if (!deps.has(name)) {
        deps.set(name, new Set())
      }

      for (const dep of dependencies) {
        deps.get(name).add(dep)
      }
    } else {
      throw {
        code: 2,
        message: `error: line ${lineNum}: unknown directive ${directive}`
      }
    }
  }

  // Validate that all dependencies refer to declared tasks
  // Process in the order they first appear in input
  const allNames = new Set()

  // Rebuild in order: first pass to collect all referenced names
  lineNum = 0
  for (const rawLine of lines) {
    lineNum++
    const line = rawLine.trim()
    if (!line || line.startsWith('#')) {
      continue
    }
    const words = line.split(/\s+/)
    if (words.length === 0 || words[0] === 'task' || words[0] === 'dep') {
      // Process in a second pass for deps
    }
  }

  // Check all dependencies reference declared tasks
  for (const [taskName, depSet] of deps) {
    for (const dep of depSet) {
      if (!tasks.has(dep)) {
        throw {
          code: 2,
          message: `error: unknown task ${dep}`
        }
      }
    }
  }

  return [tasks, deps]
}
"}

