{"file_path":"src/commands.js","content":"/**
 * Implement the three commands: waves, explain, and pack.
 */

/**
 * Print tasks grouped by their dependency depth (waves).
 */
export function waves(graph) {
  const tasks = graph.getAllTasks()

  if (tasks.length === 0) {
    process.stdout.write('total 0\n')
    return
  }

  // Group tasks by depth
  const waveMap = new Map()
  for (const name of tasks) {
    const depth = graph.getDepth(name)
    if (!waveMap.has(depth)) {
      waveMap.set(depth, [])
    }
    waveMap.get(depth).push(name)
  }

  // Find max depth
  let maxDepth = -1
  for (const depth of waveMap.keys()) {
    maxDepth = Math.max(maxDepth, depth)
  }

  // Print waves
  for (let i = 0; i <= maxDepth; i++) {
    const wave = waveMap.get(i) || []
    wave.sort()
    process.stdout.write(`wave ${i}: ${wave.join(' ')}\n`)
  }

  // Calculate total makespan
  let total = 0
  for (const name of tasks) {
    const finish = graph.getFinish(name)
    total = Math.max(total, finish)
  }

  process.stdout.write(`total ${total}\n`)
}

/**
 * Print each task with its start, finish, and depth.
 */
export function explain(graph) {
  const tasks = graph.getAllTasks()

  for (const name of tasks) {
    const start = graph.getStart(name)
    const finish = graph.getFinish(name)
    const depth = graph.getDepth(name)
    process.stdout.write(`${name} start=${start} finish=${finish} depth=${depth}\n`)
  }

  // Calculate total makespan
  let total = 0
  for (const name of tasks) {
    const finish = graph.getFinish(name)
    total = Math.max(total, finish)
  }

  process.stdout.write(`total ${total}\n`)
}

/**
 * Simulate scheduling tasks on multiple workers.
 */
export function pack(graph, numWorkers) {
  const tasks = graph.getAllTasks()

  if (tasks.length === 0) {
    process.stdout.write(`makespan 0\n`)
    return
  }

  // Track worker state: [time, tasks scheduled on this worker]
  const workers = Array.from({ length: numWorkers }, () => ({ freeAt: 0, tasks: [] }))

  // Track finish times of all tasks
  const finishes = new Map()
  const starts = new Map()

  // Queue of ready tasks (that can start immediately)
  const readyTasks = new Set()

  // Calculate which tasks are initially ready (no dependencies)
  for (const name of tasks) {
    const deps = graph.getDependencies(name)
    if (deps.size === 0) {
      readyTasks.add(name)
    }
  }

  // Track completed tasks
  const completed = new Set()

  // Simulation loop
  while (completed.size < tasks.length) {
    // Find the next time at which something can start
    let nextTime = Infinity
    for (const worker of workers) {
      if (worker.freeAt < nextTime) {
        nextTime = worker.freeAt
      }
    }

    if (nextTime === Infinity) {
      break
    }

    // Get all tasks that are ready at this time
    const currentReady = new Set()
    for (const name of readyTasks) {
      if (!completed.has(name)) {
        currentReady.add(name)
      }
    }

    // Assign tasks to free workers
    while (currentReady.size > 0) {
      // Find a free worker
      let freeWorkerIdx = -1
      let minFreeTime = Infinity

      for (let i = 0; i < workers.length; i++) {
        if (workers[i].freeAt <= nextTime && workers[i].freeAt < minFreeTime) {
          minFreeTime = workers[i].freeAt
          freeWorkerIdx = i
        }
      }

      if (freeWorkerIdx === -1) {
        break
      }

      // Get the task with highest priority, breaking ties by name
